import com.comsol.model.*;
import com.comsol.model.util.*;

public class Run {
  public static void main(String[] a) throws Exception {
    ModelUtil.connect("localhost", 2036);
    ModelUtil.showProgress(true);
    Model model = ModelUtil.load("Model", "C:/models/busbar.mph");
    model.study("std1").run();
    model.save("C:/models/busbar_out.mph");
    ModelUtil.remove("Model");
    ModelUtil.disconnect();
  }
}
// compile & run: comsol compile Run.java  then  comsol batch -inputfile Run.class (or java with the COMSOL jars on the classpath)

model.component("comp1").geom().create("geom1", 2);
