// Model.java
import com.comsol.model.*;
import com.comsol.model.util.*;
public class Model {
  public static Model run() {
    Model model = ModelUtil.create("Model");
    model.param().set("L", "0.1[m]");
    model.component().create("comp1", true);
    model.component("comp1").geom().create("geom1", 3);
    // ... geometry, physics, mesh, study ...
    return model;
  }
  public static void main(String[] args) { run(); }
}
// shell:
comsol compile Model.java
comsol batch -inputfile Model.class -outputfile Model_out.mph -batchlog Model.log

// Application method: validate an input field before computing
double w = model.param().evaluate("w");
if (w <= 0) {
  alert("Width must be positive", "Invalid input");
  return;
}
if (confirm("Solving may take several minutes. Continue?", "Compute", "Continue", "Cancel")) {
  model.study("std1").run();
}

startProgress("Parameter sweep");
double[] widths = {1, 2, 3, 4, 5};
for (int i = 0; i < widths.length; i++) {
  setProgress((int)(100.0*i/widths.length), "Solving width = " + widths[i] + " mm");
  model.param().set("w", widths[i] + "[mm]");
  model.study("std1").run();
  if (isCancelled()) break;
}
closeProgress();

// Method called by a 'Compute' button
model.study("std1").run();
with(model.result("pg1").feature("surf1"));
  set("expr", "T");
  set("unit", "degC");
endwith();
model.result("pg1").run();
useGraphics(model.result("pg1"), "graphics1");
zoomExtents("graphics1");

long t0 = System.currentTimeMillis();
model.study("std1").run();
double secs = (System.currentTimeMillis() - t0)/1000.0;
message("Study 1 finished at " + timeStamp() + " in " + secs + " s");
double Tmax = model.result().numerical("max1").getReal()[0][0];
debugLog("Tmax = " + Tmax);
if (Tmax > 400) alert("Temperature limit exceeded");
